<style>
.admin-header{display:flex;align-items:end;justify-content:space-between;gap:24px;margin-bottom:28px}.admin-header h1{margin-bottom:8px}.admin-header p{margin-bottom:0}.admin-badge{padding:8px 12px;border:1px solid #f1dfcc;border-radius:999px;background:#fff7ee;color:#c96825;font-size:11px;font-weight:700;white-space:nowrap}.admin-upload-card{grid-template-columns:auto 1fr minmax(340px,460px);margin-bottom:34px}.admin-upload-form{display:flex;flex-direction:column;gap:10px}.admin-file{display:flex;align-items:center;gap:10px;padding:12px 14px;border:1px dashed #e5cdb8;border-radius:12px;background:#fff}.admin-file input{width:100%;font-size:12px}.admin-upload-form .button{align-self:flex-start}.admin-status{min-height:18px;margin:0!important;font-size:12px}.admin-list{display:grid;gap:18px}.admin-empty{padding:40px;background:#fff;border:1px solid var(--line);border-radius:18px;text-align:center}.admin-recipe{display:grid;grid-template-columns:minmax(0,1fr) 240px;gap:24px;padding:24px;background:#fff;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 25px rgba(83,54,28,.04)}.admin-recipe-id{display:inline-flex;margin-bottom:13px;padding:5px 9px;border-radius:6px;background:#f7f3ed;color:#8a857e;font-size:10px;font-weight:700}.admin-edit-form{display:grid;gap:12px}.admin-field{display:grid;gap:6px}.admin-field label{font-size:11px;font-weight:700;color:#665d54}.admin-field input,.admin-field textarea{width:100%;border:1px solid #e7e0d8;border-radius:10px;padding:11px 12px;outline:0;background:#fffdfa;color:var(--ink);resize:vertical}.admin-field textarea{min-height:92px;line-height:1.55}.admin-field input:focus,.admin-field textarea:focus{border-color:var(--orange);box-shadow:0 0 0 3px #fff0e4}.admin-actions{display:flex;align-items:center;gap:10px}.admin-actions small{color:var(--muted)}.admin-photo-form{display:grid;align-content:start;gap:11px}.admin-photo-preview{width:100%;aspect-ratio:4/3;object-fit:cover;border-radius:13px;background:#f7f3ed;border:1px solid var(--line)}.admin-photo-empty{display:grid;place-items:center;width:100%;aspect-ratio:4/3;border-radius:13px;background:#f8f5ef;color:#aaa39a;font-size:12px}.admin-photo-form input{width:100%;font-size:11px}.admin-photo-form .button{width:100%}@media(max-width:900px){.admin-upload-card{grid-template-columns:auto 1fr}.admin-upload-form{grid-column:1/-1}.admin-recipe{grid-template-columns:1fr}.admin-photo-form{grid-template-columns:160px 1fr;align-items:center}.admin-photo-preview,.admin-photo-empty{grid-row:span 2}}@media(max-width:560px){.admin-header{display:block}.admin-badge{display:inline-flex;margin-top:14px}.admin-upload-card{padding:18px}.admin-photo-form{grid-template-columns:1fr}.admin-photo-preview,.admin-photo-empty{grid-row:auto}.admin-actions{align-items:stretch;flex-direction:column}.admin-actions .button{width:100%}}
</style>
<section class="page-head admin-header"><div><div class="eyebrow">ADMINISTRASI</div><h1>Kelola resep</h1><p>Kelola dataset, konten, dan foto resep dari satu tempat.</p></div><span class="admin-badge">AREA ADMIN</span></section>
<section class="embedding-card admin-upload-card"><div class="embedding-card-icon">▦</div><div class="embedding-card-copy"><div class="eyebrow">DATASET RESEP</div><h2>Tambah atau perbarui koleksi</h2><p>Gunakan template agar nama kolom sesuai. ID yang sama akan mengganti resep lama.</p><a class="button secondary" href="{{ route('admin.recipes.template') }}">Download template Excel <span>↓</span></a></div><form class="admin-upload-form" id="admin-import-form" action="{{ route('admin.recipes.import') }}" enctype="multipart/form-data">@csrf<label class="admin-file"><span>📄</span><input type="file" name="file" accept=".csv,.xlsx" required></label><button class="button" type="submit">Impor dataset <span>↗</span></button><p class="admin-status" id="admin-import-status" role="status"></p></form></section>
<section class="embedding-card admin-embedding-card"><div class="embedding-card-icon">✧</div><div class="embedding-card-copy"><div class="eyebrow">KNOWLEDGE BASE</div><h2>Perbarui pencarian chatbot</h2><p>Jalankan setelah import atau edit resep selesai. Proses ini membuat ulang embedding seluruh koleksi.</p></div><div><button class="button" id="admin-embedding-button" type="button">Jalankan embedding <span>↗</span></button><p class="admin-status" id="admin-embedding-status" role="status"></p></div></section>
<section class="admin-list" id="admin-recipe-list"><div class="admin-empty">Memuat koleksi resep...</div></section>
<script>
(() => {
    const list = document.querySelector('#admin-recipe-list');
    const status = document.querySelector('#admin-import-status');
    const csrf = document.querySelector('meta[name="csrf-token"]').content;
    const escape = value => String(value || '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' })[character]);
    const render = recipes => { list.innerHTML = recipes.map(recipe => `<article class="admin-recipe"><div><span class="admin-recipe-id">ID ${escape(recipe.id)}</span><form class="admin-edit-form" data-update="${escape(recipe.id)}"><div class="admin-field"><label>Nama resep</label><input name="title" value="${escape(recipe.title)}" required></div><div class="admin-field"><label>Bahan dan takaran</label><textarea name="ingredients" required>${escape(recipe.ingredients)}</textarea></div><div class="admin-field"><label>Langkah memasak</label><textarea name="steps">${escape(recipe.steps)}</textarea></div><div class="admin-actions"><button class="button" type="submit">Simpan dan embedding <span>↗</span></button><small class="admin-form-status" role="status"></small></div></form></div><form class="admin-photo-form" data-photo="${escape(recipe.id)}" enctype="multipart/form-data">${recipe.photo_url ? `<img class="admin-photo-preview" src="${escape(recipe.photo_url)}" alt="${escape(recipe.title || 'Foto resep')}">` : '<div class="admin-photo-empty">Belum ada foto</div>'}<div><label class="admin-field"><span>Foto resep</span><input type="file" name="photo" accept="image/*" required></label><button class="button secondary" type="submit">${recipe.photo_url ? 'Ganti foto' : 'Upload foto'}</button><small class="admin-form-status" role="status"></small></div></form></article>`).join('') || '<div class="admin-empty">Belum ada resep di MongoDB.</div>'; };
    const load = async () => { const response = await fetch('{{ route('admin.recipes.data') }}'); const data = await response.json(); render(data.recipes || []); };
    document.querySelector('#admin-import-form').addEventListener('submit', async event => { event.preventDefault(); status.textContent = 'Memproses dataset...'; const response = await fetch(event.currentTarget.action, { method: 'POST', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': csrf }, body: new FormData(event.currentTarget) }); const data = await response.json(); status.textContent = data.message || 'Selesai.'; if (response.ok) await load(); });
    document.querySelector('#admin-embedding-button').addEventListener('click', async event => { const button = event.currentTarget; const embeddingStatus = document.querySelector('#admin-embedding-status'); button.disabled = true; embeddingStatus.textContent = 'Membuat embedding seluruh resep...'; try { const response = await fetch('{{ route('admin.recipes.embeddings.build') }}', { method: 'POST', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': csrf } }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Embedding gagal.'); embeddingStatus.textContent = `${data.message} Total: ${data.count || 0}.`; } catch (error) { embeddingStatus.textContent = error.message || 'Embedding gagal.'; } finally { button.disabled = false; } });
    list.addEventListener('submit', async event => { event.preventDefault(); const form = event.target; const statusNode = form.querySelector('.admin-form-status'); const id = form.dataset.update || form.dataset.photo; const isPhoto = Boolean(form.dataset.photo); const button = form.querySelector('button'); button.disabled = true; if (statusNode) statusNode.textContent = isPhoto ? 'Mengunggah...' : 'Menyimpan dan membuat embedding...'; try { const response = await fetch(isPhoto ? `/admin/recipes/${id}/photo` : `/admin/recipes/${id}`, { method: isPhoto ? 'POST' : 'PATCH', headers: { Accept: 'application/json', 'X-CSRF-TOKEN': csrf, ...(isPhoto ? {} : { 'Content-Type': 'application/json' }) }, body: isPhoto ? new FormData(form) : JSON.stringify(Object.fromEntries(new FormData(form))), }); const data = await response.json(); if (!response.ok) throw new Error(data.message || 'Perubahan gagal.'); if (statusNode) statusNode.textContent = data.message || 'Berhasil disimpan.'; if (isPhoto) await load(); } catch (error) { if (statusNode) statusNode.textContent = error.message || 'Perubahan gagal.'; } finally { button.disabled = false; } });
    load();
})();
</script>
